//! Vanilla 26.3 data tables, generated by tools/gen_data.py from the vanilla
//! jar. Loaded once at startup (`rine_data::init()`), then accessed lock-free
//! through `rine_data::get()`.

pub mod registry;
pub mod blocks;

use std::sync::OnceLock;

pub use registry::Registries;

pub struct Data {
    pub registries: Registries,
    pub blocks: blocks::Blocks,
}

static DATA: OnceLock<Data> = OnceLock::new();

pub fn init() -> &'static Data {
    DATA.get_or_init(|| {
        let registries = Registries::load();
        let blocks = blocks::Blocks::load(&registries);
        Data { registries, blocks }
    })
}

#[inline]
pub fn get() -> &'static Data {
    DATA.get().expect("rine_data::init() not called")
}
